) AS (
  VALUES 
    (226::BIGINT, 'Profe bastante decente aunque solo tuve medio semestre con él, brinda apoyo pero a veces cuesta entenderle. Por lo demás solo necesita prestarle atención y le irá bien'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '4a3aa270d5081c310bbfc88f99ba21dbb8a69ef0359fc661138e48370da1f089'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Califica duro pero si pone atencion le va bien en los quices.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'a6b91886adf67ac52883f8a0e394632412d6e917a9ea4420d6855f2a5bf255cd'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Para explicar es muy malo, no lo recomiendo para llevar el curso por primera vez, sin embargo califica relativamente suave'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'af809f9c66d57cac27070e5341bcc0d148f98e7f4ce019f6c96aba50489e4fdc'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Explica bastante bien y da buena retroalimentación. Los quices son relativamente faciles si ud pone atención.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-02-12T00:00:00+00:00'::TIMESTAMPTZ, '14eca33d7a64737c632d135b18ed5676c0e92183c58d752ebd558ecfb323af34'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Excelente profesor, explica claro y además está consiente de la naturaleza del curso, por lo que lo evalúa acorde a esto. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f8cda879b571e489e80a86ebdbd976e7e2a25fea5d4d078b9da5e9fd21c396ab'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'El profe es bueno, sabe mucho y explica bastante bien. Las clases son demasiado largas así que lleve un buen café. Califica bien, el curso es duro entonces trabaje bastante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases largas']::TEXT[], '2024-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'b72588b07726fc23f4484c93ba2b162080cb84ff09f18c3a0cb8e9daa44f83d6'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Si matricula con él va a llevar primero el módulo de soldadura. Dicho esto el profe en sí es un grande. muy buena nota y lo ayuda bastante. Los quices son durillos si uno se despista pero si pone bastante atención en clase se pasa. Igual matricule mejor con Julio por que soldadura es menos pesado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, '042ef86c2603847cd163afadd562a8df5e3770d8b5c0eea127bc771eb1d00703'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Es super pura vida, se pasa bastante fácil. Hace quices que todo lo que preguntan lo dio en la primera clase, pregunten a los del grupo de antes, siempre es el mismo quiz'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-26T00:00:00+00:00'::TIMESTAMPTZ, '8ea47d82098a40e70c90bea142488665cf12ac542a43ce01edafec9014407ab4'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Con este profe se lleva la mitad del curso. Todo se hace en el laboratorio, no deja tareas. Hace quizzes un poco complicados de dos preguntas entonces hay que poner mucha atención. Esta es la parte más fácil de laboratorio.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '55179c89789a472ee7dc75e1eb1be7aad6980a0b785ba8b7ff0056f3ff9d7ed5'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd438c95d69e5892b0c1c46d555fec2f04def9ad36af2dcd5f7e0c13e4875db27'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Buen profesor, hay que demostrar interés en los cursos, sino, te ficha y lo pone de piso el resto del semestre. Califica suave, comunicación clara en las evaluaciones, él califica conocimiento, no le interesa la teoría.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b4297eb6fa20f2bc3edb916af937ee3571718079b85069e7092ee5ca9705f742'::TEXT, ARRAY[1179, 642]::BIGINT[]),
    (226::BIGINT, 'Depende mucho de usted y su grupo como se lleve con el profe, con el mio fue excelente, con otros una persona desagradable. Desde mi experiencia, uno de los mejores profes que he tenido en mante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3a0d571b31e1958f557f0d0c13455c1f267fa85e9f7558d4aac88bb97e6046b2'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Perfecto profe para recuperar o recursar, NO lo recomiendo para la primera vez. En verano él se enfoca en lo importante, nada muy profundo o completo. La parte de descriptiva la califica con 4 examenes cortos y un proyecto. Lo demás con 2 proyectos individuales. Es buen profe, pero fuera de catedra.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos exámenes']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, '44e06e8f73228f9c454ed8453b1e0254c07dce57241a9f09ed66581fa0fe4eef'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'La materia del curso es fácil, la clave esta en formar un buen equipo de trabajo, ya que los trabajos son bastante grandes y si no trabajan todos es complicado. El profe explica bien, se entiende bien si va a consulta le ayuda con las dudas pero en generar muy bien'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7c91406ce3f588ebf8851960fa552156716bcab7903619e2eb52b7de4928d888'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'El profe es super buena nota, califica suave, intenta ayudar mucho al estudiante. Pero no sabe expresarse bien a la hora de explicar, sin embargo es muy interesante el curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd23a8ccbbf800d8392e532a85da8f9d6be3cef5d92b52eb11d17b1a9ce8f6c5c'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'El curso es muy pesado, pero este profe ayuda demasiado para pasar, ya que explica excelente y califica extremadamente suave. Solo hay que ponerle en el primer examen y mucho cuidado con el grupo de trabajo, por que los proyectos son muy densos y DI se pasa en grupo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-06-19T00:00:00+00:00'::TIMESTAMPTZ, '623dbd37b88b944ebc07c1b52d4999647d73620f3da32c903637ed13bad2c753'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'En general es un buen profe. Explica claramente, y da ayuda cuando se le pide. En ocasiones puede ser algo sarcástico, y se molesta si se le pide que repita varias veces sus explicaciones. Sin embargo, todo lo negativo se compensa con lo suave que califica cada trabajo. Se pasa fácil con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'bec0b45c68ba127fe8bbbd2e82574f8af34fc07bd52b1bf1715bf7f566ab70ef'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Es muy fácil pasar el curso con él, además de que explica super claro y lo ayuda si uno ocupa ayuda. Califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0f5c2e98713699a744aa392991fc2450ad93cd435b232c6e0a756601d701ad1d'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Super buena nota el profe. Solo ponga atención en como abrir y cerrar los tanques de acetileno sino es un toque sarcástico. Pero dele sin miedo, super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e76f450dd764c225f4aceca97ec813a9682d089493ac8fffd710db63b35057ca'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Es buena opción para este curso. Explica la mayoría de los temas, pero el curso sigue siendo un poco autodidacta. Es muy desordenado. No califica muy duro y da buena retroalimentación, pero hay que irle preguntando e ir a las consultas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '84ff745449c4611e805f20dfb1983231473955b5c08df2344beb8239d569f177'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b251de816a9ff346256e744565253657ca0c308790ad8fd08b14d070176b7096'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'No explica nada, califica super duro ya que no deja claro los puntos a calificar y quita puntos por lo que el quiera, se enreda a la hora de usar los programas'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '22abb8b93ee88266f4362eff50d2a57c8e66d4e6ebdc1e13fb818bdd92728621'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Es una materia muy dura y este profe lo hace mas difícil, asume que ya todos sabemos AutoCad y SW y no explica cosas de esos programas, nada mas deja y deja tareas y revisa super duro, cualquier error pequeñito lo ve.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '42c5d0fc6aaa9e01a30481ce7d260117aaff6eb97790596ec85b85f66bb58b0b'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Hay que ser autodidacta ya que el mismo profe dice que las clases son para resolver dudas o en ocasiones explica cosas muy puntuales. Muchas veces es comprensivo y extiende las fechas de entrega de los trabajos. Califica suave y uno le puede escribir por WhatsApp si se tiene alguna duda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '3cd29ef949545f8fa0449e09f9c61bd24a4639483d941baf8647fc4cf1a0ae05'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Se enreda un toque explicando, se lo recomiendo si no tiene que llevar dibujo industrial, se pasa fácil y hace trabajos y examen final en grupo, por lo que su nota depende un poco de eso. Pone Tareas sin explicar, basese en el material semanal si no sabe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4d3159030c79f3556d17ece19ffdfdc5d1b3e60f62d3bb7a16590e240d4f09f7'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Virtual. Es de lo mejorcito que hay. En las tareas y quices pone 100. Sus clases son más como para aclarar dudas, ya que hay que ser autodidacta usando el material de la cátedra.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '40b39c38edbb44d91be9cb9ff56ceeb00c7bbbf6cb1a48c5ff3ed7c12ff47eda'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'La verdad es el profe más comprensivo para este curso, sin embargo es sumamente aburrido y explica poco en clases (todo está en la cátedra, pero el material no es tan bueno). Lo que explica queda claro pero siento que podría mejorar un poco más. Recuerde que D.I se pasa en grupo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'd46e73319f101dcca0c55a20377149b892d8499b118f49b2f51116dcfba7e4da'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'El profe califica de forma muy suave (al menos en formato virtual) por esta razón les recomendaría matricular con él, pero si lo hacen también les aconsejo que nunca vayan a consulta extracurricular. Se interesa más por la consultas de chicas que de chicos (Aspecto a tomar en cuenta).'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, '88cdb82f7bea8012be567afaabb5cef1548a9c1df0c552b9dd60613d060440e2'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-10T00:00:00+00:00'::TIMESTAMPTZ, '807464621d0f9c7ca2742645508d4a82bc3a5c3558f874a99735eb2cb75b95ff'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Una teja de profe, las clases pueden hacerse muy largas xq a ratos se hace bolas, pero comparte muchas mañas, trucos y secretos q hacen la clase muy fácil, si ud muestra interés él le responderá las dudas. Es muy flexible y busca ayudar al estudiante, (ojalá q se lea un toque el INTE-ISO)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '415872c2c7ddd38886d669001f352b41df2c6923d1e826c668c955cca991f7f2'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Explica super bien y de forma muy clara. Tarda mucho para revisar las tareas y los examenes, pero califica justo. Hace el curso menos pesado de lo que es. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '2e3203c491010b282c07652b98aa2010b5a3765334afd16f750b2ceaf6936475'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Buen profe para dibujo, se ve lo necesario y califica justo, en general no complica tanto el curso, solo hizo 2 exámenes, el segundo fue grupal, hay varias tareas y evaluaciones de seguimiento, hay que poner atención en clase porque no envía correos de las evaluaciones de que deja.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'cf73963fba70a171a4a3d4797108906ae4a760ad63b4562d13a17e5c871c32aa'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Me parece la mejor opción si su carrera no ocupa mucho dibujo. Califica suave y explica bastante bien. Es muy buena gente y accesible en horas de consulta y correo. No es muy meticuloso a la hora de revisar, por lo que si entrega todo va a pasar fácil. Suele dar tiempo extra para las entregas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'cc433833a940ae5bde6b9e2a9df7276ed38e90a384f632ba1adab926d7092d08'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Explica bien, evalúa relativamente suave hasta llegar a los exámenes. Le pone más énfasis a SolidWorks que AutoCAD. Recomendado para pasar dibujo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '185257b7e3f6b558b5ceed4b7e02b770061c7331b75bbc064c023a05ab557d14'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Explica bien, si no entiendes te vuleve a explicar, pero si es algo que ya explico aveces lo disgusta, pero todo bien, ponga atencion y si no sabe pregunte'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'eeec6a62629ffd5d9aef3635ac7655f994e5240543f6615ae1db25b309003a1c'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'El mae es muy desordenado, llega tarde siempre y no es bueno explicando, quizas pase el curso porque con el es fácil, pero no va a aprender nada. Lo recomiendo si es de produ o electro pero no si es de materiales'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-18T00:00:00+00:00'::TIMESTAMPTZ, '330fe810b2578f8e49d6bfc178f827591e9f52d7041ad2f5bd7167fdf875a367'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'El curso es muy pesado en cuanto al tiempo que hay que dedicarle. El profe en el tema de geometría descriptiva exolica regular, en ocasiones se enoja si uno no entiende,él siempre recibe reclamos y ayuda a sacar los hasta el día de entrega de actas,es bastante accesible en los reclamos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'd4cb00192043fbd8d1aee0c6dda5d77bf9ecf181b8a1a7402572fa0f43ec5b31'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'La verdad es el mejor profe de DT a mi punto de vista, hasta da chance de eximirse sin haber entregado ninguna tarea que se hacen tediosas (con todos los profes) ayuda mucho si se le pregunta hasta aclara bien las dudas durante los exámenes, profundiza más solidworks que AutoCAD.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'e4baa1d7098cf46f946093f1e82ff3c4a4bdd6280c63618d5ae6271cf207aae0'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Es buen profe, a veces se le va un poco la paciencia cuando le preguntan algo que ya explico muchas veces, así que ponga atención. El profe exime si usted lleva una buena nota y el curso para ser tan pesado el profe lo ayuda a hacer más ligero'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '08955925d14244fa6877a7ebe25c145d538843829e89b22a359ceb2de7d17c14'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Muy buen profe en mi opinion, no tan bueno en geometria descriptiva; las tareas usualmente da 100 en todas, solo que se vean decentes; hay que hacerle spam, porque casi no responde emails o mensajes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '526a742847970e36543c3198b3bda0b79230ef31f4dc348485e6ee721485964c'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'El profe explica muy bien y se preocupa porque uno entienda, los quices son faciles, no pasa asistencia y casi todos los trabajos son en grupo, pero el escoge los grupos por orden de lista, es muy bueno lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd7809bd8195a04f06223a8765334b2c70ceae94fd48145ade756fdf2707aaa90'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Mae si quiere llevar con este mae tiene que entender todo a la primera, si usted no entiende y le pregunta una o dos veces el mae se enoja y no le explica bien.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-24T00:00:00+00:00'::TIMESTAMPTZ, '9133e718ad842197a2f96f16856e01e687f34c41b87b8286946886033f9a1e42'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'El curso es tedioso pero el profe lo hace ameno. Tiene que hacer todas las tareas y las supervisadas para pasar, ponga atención en clase y practique y el curso con él es fácil. Quices fáciles, solo que aveces puede ser un poco odioso pero por lo general es muy buena gente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-26T00:00:00+00:00'::TIMESTAMPTZ, '0ee4be71b907ec71915a1d4fd91383f08f4cae14505c4726294b94927512564c'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'El profe explica muy bien, te atiende siempre, y aparte de explicar bien no califica rudo, totalmente recomendado... Tanto asi que matriculare cuando pueda con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-19T00:00:00+00:00'::TIMESTAMPTZ, '61a8036c101f5a86239b4e5a156b3af01b78e23f128acdbb8c9ce3de78113095'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Muy buena gente. Explica con claridad e indica de antemano lo que entra en los quizes. En general revisa muy suave y está más interesado en que uno aprenda y disfrute el laboratorio que en hacerlo sufrir. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-09-17T00:00:00+00:00'::TIMESTAMPTZ, 'd28d13e8d665fcf65fc7579d57746ac729be6962ae042cf8decd48fd8e4e75de'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Le falta ser un poco más ordenado con su tiempo y con sus clases, pero después de eso es un excelente profesor, sabe mucho y no le molesta explicar 2 o 3 veces y es muy flexible, totalmente recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, '508ee3d285dd91d1561264185428af64894a384cf0d12ee08cc9be8725a57106'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Un crack y muy pura vida'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '88a48976cbf67535578858289a5a9dd52c53ca0957b6b9cb8f0be8e1a64a61f0'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'El curso es increíblemente pesado, el profe lo hace más accesible, la verdad creo que explica bastante bien para el curso que es'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '4622d2e9eb1995bd4e41580dab633f08302506c482f668ab573b251d833d965a'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Buen profe para el lab, no califica duro, ayuda bastante y es buena nota'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9ee0dae804c18b6236a1cb3f49659a4be1fbafd875f9dfb47b64e05e072498fb'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'No pasa lista. Califica bastante suave aunque se enrede solo explicando.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, '3c653a4903e8c3bc56c20f1b382cbca50340c7e29d80b2724d4ec852349df5fe'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-03-30T00:00:00+00:00'::TIMESTAMPTZ, '2208bda178e776a94fd45485e93e366327e6adb390d1bccfcf393fbd142cae99'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Clases largas']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '97ad8aca7a7d0610ffcd8d20ec5cdfb9e754a71cb3af0e6c0f0e8fe64b0ad82e'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'No pasa lista... se complica al explicar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '4801097d6199fd78b9d2aad89607fbdbc1f7ad906c339c1ab083a450e019a1a1'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Se confunde mucho cuando explica y califica muy rudo. Ayuda bastante, pero si le cuesta dibujo no lo meta con él.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '781eab2ba8b9074b77c3b7dcbcf0bbba1cbb74eaa11334d2788174539e553457'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Realmente califica muy suave, en clase atiende las dudas unas mil veces aunque a veces se enrede el solo. Recomendado para pasar el curso'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ff2d61781501408d37aff023c253f18b4895ebc30fa1c4837123fe5edb5b63b0'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Los quices son faciles y califica según el avance que se tenga'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, '46f4cb60a770d3061f57eae03bcd8fda1145a2d045b9ddbca42e4c8466a1530c'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Dio por primera vez. Algo enredado en la explicación, se notaba la falta de experiencia. En general, buena persona y sí sabe hacer las cosas. Busque ir a clases, poner atención y preguntar. Él ayuda. Evaluaciones aparte de exámenes bastante accesibles. Curso 100% pasable y es de por sí fácil'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e04ad08a6c864304d040d5b1bfd231bd727f1635ab6d90d459d003d436cc6eb6'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Califica demasiado duro, es bueno y trata de ayudar pero califica mortal y no explica muy bien los programas, hay que ser autodidacta.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'eb1af14a7e5b729d435f088745159f193ededde0a97da513016138363f44284c'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'La verdad es el profe más comprensivo para este curso, sin embargo es sumamente aburrido y explica poco en clases (todo está en la cátedra, pero el material no es tan bueno). Lo que explica queda claro pero siento que podría mejorar un poco más.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2477a6f34648d89a915e259b9977afe2c07a87f021adf58d383dfaf52b29eb3d'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Excelente profe y persona, dele sin miedo va aprender y califica suavitel'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'f72b78377db4798b1badcfbe0c2debf55d767a53302f34648e67766afe5cba0d'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Hay brete todas las semanas, quita bastante tiempo, pero se hace. El profe solo revisa exámenes y no es carepicha para calificar, lo que son tareas ya depende del asistente. Solo no falte y haga los trabajos, el mae es pura vida'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'f3e449fb8c93d67331a545bd948f46ea67c555099f2f76cf7aaf096f63937b07'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Para los profes que hay, es el mejor. Siempre anda perdido con el cronograma, pero da tiempo extra para las tareas, que casi ni las revisa, entonces suelen ser puros 100. Si puede matricular con él... dele viaje'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a29cbccc5a894b9b738876ba6f50e43f35e926e7d8ee68f53d51aa46afeff032'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Tiene mucha experiencia dando la materia de dibujo técnico e industrial, explica muy claro, y si uno llega a consulta explica las veces que sea necesario, además aprecia el esfuerzo de los estudiantes, califica muy suave. Recomendado para cualquier curso de la escuela de electromecánica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '43b8cfa57c7dda77161fcd2db2bd7b64683c863ef097bb12f704a71dace8f986'::TEXT, ARRAY[933, 610]::BIGINT[]),
    (226::BIGINT, 'Se lo pongo así, un quecazo!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ea0d32955f6b7845f8c2ecd539d303a77dac1c5083910f8b815e46e063810875'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Excelente profesor, explica bastante bien y atiende todas las dudas, nunca tiende el cronograma presente pero suele dar un par de días más para la entrega de tareas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '4786cbf71cf1b88be9b4db4f1741c3caa116065e14152348fd4cf9393e0d6bb1'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Excelente explicando, no tiene problemas en responder cualquier duda. A veces anda perdido con el cronograma pero no afecta mucho. Califica suave quices, tareas y proyecto. Es de los mejores, no complica el curso innecesariamente como otros.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bf81a0f99e5877172d5a08bdd411b37bb81458962932415cd388ed45d9e4c3aa'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'El profe cae excelente, explica demasaido bien hasta que uno entienda, aclara dudas y ayuda si ve que a uno le cuesta, califica suave en el lab y los quices, se disfruta demasaido las clases con el. La mejor opción para soldadura.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd2199a01d6d17f5885d37ba51a00543f2e77cfcdf3d4546317d5bcac564e6db5'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Es un muy buen profe ayuda bastante. El truco para llevar precisión primero y luego soldadura con él es matricular un grupo impar de lab que tenga a Julio (preferiblemente) y grupo par siguiente que lo tenga a él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5bf5c9e9cdba5e10e47e1deaa27891843efebd633775054fe91dcfc69cdc7b55'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Le falta ser un poco más ordenado con su tiempo y con sus clases, pero después de eso es un excelente profesor, sabe mucho y no le molesta explicar 2 o 3 veces y es muy flexible, totalmente recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, '951ff12489c94cbde929959177151350f9d3069c3a06454e99ea3006a7388060'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Explica bastante bien (a veces es medio desordenado, pero se le entiende la materia). Es consciente de que el curso es demasiado pesado, entonces da más tiempo para las tareas y evaluaciones en general. Busca cómo ayudar al estudiante a pasar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '58cf43aa43dce654d77442405da1d7c87630b9e9f764e63e8f6b2a80375d46fc'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Muy bueno. Explica bien, ayuda mucho y no tiene problema en aclarar dudas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '76308f2d12683584c32102323f8bc452ba1dcf2963dff89d26212e460befb9f4'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Para un curso tan complicado como este, es un profesor excelente, le da ayuda a uno hasta donde él puede dar, buena gente y paciente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'fb8106fca3a7957ae1e5e9b44be4a9a6e02c09da4dd78d1da12376a5131e0320'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'El curso como es tan colegiado da poco donde el pueda ayudar pero si califica más sueve comparado a los demás, en consulta y en clases se preocupa porque usted entienda con claridad. No le de miedo preguntar. Si lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '80c80a0e7cae3aaf214186e00790c843a31b93dc72cee80b18b0b1e5bdb9d6d2'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Un profe muy pura vida, va al suave y ayuda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '36f7cf9eea4fc5cca10b2df60a452e871ee34fbd5f1b9e25b927a5c615ae5444'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'clases de mucho provecho, a veces demasiado teóricas, explica las veces que sean necesarias, en consulta excelente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd63f3d0536c168206fe4ef8a3ff01e2696bb192affd9fa5b3f39a067650d3ba6'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'D.I. es un curso bastante pesado, tanto para entender como explicar, este profe tiene madera para ser bueno, ademas de preocuparse por sus estudiantes'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-25T00:00:00+00:00'::TIMESTAMPTZ, '0e23147a6586ffc38a717e1af0886164d2769206c984c974c4b09675309cc734'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'se preocupa por el estudiante, no le importa explicar 100 veces excelente persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'b3b279c197e4a88060bf25bb28566eca6bd844bd9d84d827cbf439479520475c'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Muy agradable, aclara dudas, busca que uno entienda. Lo recomiendo porque hace llevadero el curso, y se puede pasar de lo más bien. En cuanto a claridad en la explicación, le falta cancha, pero no deja de intentar que todos entiendan. Buen profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'd014b0f126f2be17900b1d0137b2b4937e4ff412f20cf3cf447df16f561be0a7'::TEXT, ARRAY[642]::BIGINT[]),
    (226::BIGINT, 'Es muy buena persona. Califica medio suave comparado con los demás de cátedra. Lo lleve cuando dio el curso por primera vez, y tal vez le falto algo de claridad, pero después de ya haber dado el curso considero que puede ser un muy buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5cabc7347e7c50fb2513c9708d8aeb563416948162531e4654f0930f6892d02b'::TEXT, ARRAY[933]::BIGINT[]),
    (226::BIGINT, 'Excelente profesor, explica con mucha claridad y hace el esfuerzo para que los estudiantes entiendan totalmente un tema. Toma en consideración el esfuerzo del estudiante, mas si se va a consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd139bf54ea558fc129190ece9f7ede808ba62549d4cda29ba9d471c184eb574f'::TEXT, ARRAY[610]::BIGINT[]),
    (226::BIGINT, 'Los quices son muy faciles y lo que toma en cuenta es el avance que se tenga no que tambien queden las soldaduras.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, '48d7a88cc60810736eb47aa6800cb9386c230d0c5a11a8d12720ad39f2c3ca1d'::TEXT, ARRAY[642]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
